<?php ob_start(); ?><h1><?= e(t('AI signature suggestions')) ?></h1><p class="muted"><?= e(t('Suggestions generated by clicking "Generate signature with AI" on a finding. Nothing here is applied automatically — review and click "Create signature" to save it as a real, enabled signature.')) ?></p>
<?php if(!$suggestions): ?><p class="muted"><?= e(t('No suggestions yet.')) ?></p><?php else: ?><table><tr><th>ID</th><th><?= e(t('Finding')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Name')) ?></th><th><?= e(t('Risk')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('Pattern')) ?></th><th>AI</th><th><?= e(t('Explanation')) ?></th><th><?= e(t('Actions')) ?></th></tr><?php foreach($suggestions as $s): ?><tr><td><?= e($s['id']) ?></td><td><?php if($s['finding_id']): ?><a href="/findings/<?= e($s['finding_id']) ?>"><?= e(mb_strimwidth($s['finding_path'] ?? ('#'.$s['finding_id']),0,50,'…')) ?></a><?php endif ?></td><td><?= e(t($s['status'])) ?></td><td><?= e($s['suggested_name']) ?></td><td><?php if($s['suggested_risk']): ?><span class="badge <?= e($s['suggested_risk']) ?>"><?= e(t($s['suggested_risk'])) ?></span><?php endif ?></td><td><?= e($s['suggested_type']) ?></td><td><?= e($s['suggested_pattern_type']) ?></td><td><?= e($s['ai_provider']) ?> <?= e($s['model']) ?></td><td><?= e(mb_strimwidth($s['explanation'] ?? '',0,140,'…')) ?></td><td><?php if($s['status']==='ready' || $s['status']==='needs_review'): ?><a class="btn" href="/signatures/create-from-suggestion?id=<?= e($s['id']) ?>"><?= e(t('Create signature')) ?></a><?php endif ?></td></tr><?php endforeach ?></table><?php endif ?>
<?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
